//! 🧪️ The actual mounted registry retains its original donated source through independent admission denials.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalTurnFailure,OperationId,Generation};
use semio_framework_value::retirement::controlled::ControlledRetirement;

fn position(access:&ArtifactInferenceSessionAccess<String>)->(usize,usize,u8,usize){(access.index,access.byte,access.phase,access.original().map_or(0,|value|value.as_ptr()as usize))}
fn advance(handle:&ArtifactInstanceOperationOwnerHandle,access:&mut ArtifactInferenceSessionAccess<String>,source:&mut Option<String>,cx:&mut StepContext<'_>)->Result<Option<usize>,OriginalTurnFailure>{
 handle.with_inference_session("α-model",access,cx,|cx|{if !original_inference_metadata(cx,0,1)?{return Ok(None)}Ok(source.take())},|source,cx|if original_inference_metadata(cx,0,1)?{Ok(Some(source.as_ptr()as usize))}else{Ok(None)}).and_then(|result|result.transpose().map(Option::flatten))
}
fn debit(stock:&mut RetainedCloneGrant,receipt:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation,born:&mut usize,released:&mut usize){
 assert!(receipt.fits(*stock));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));stock.maximum_items-=receipt.copied_items;stock.maximum_copy_bytes-=receipt.copied_bytes;stock.maximum_capacity_bytes-=receipt.retained_capacity_bytes;stock.maximum_release_bytes-=receipt.released_bytes;*born+=heap.requested_bytes;*released+=heap.released_bytes;
}
#[test]
fn original_mounted_inference_admission_retains_source_and_quotes_actual_registry_events(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for stop in [0,1,3,5,8,usize::MAX]{for body in [1,3,64]{
  let row=law["caller"]["stock"].as_array().unwrap();let source_grant=RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize};
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["caller"]["operation"].as_u64().unwrap()),Generation(law["caller"]["generation"].as_u64().unwrap()),source_grant,||Some(1),law["caller"]["deadlineUs"].as_u64().unwrap(),law["caller"]["fuel"].as_u64().unwrap());
  let((handle,mut source,pointer),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let handle=ArtifactInstanceOperationOwnerHandle::new(Box::new(EmptyArtifactInstanceOperationOwner));handle.with_inference_session_cold("α-document",||String::from("Existing source"),|_|Ok(())).unwrap();let source=law["payload"].as_str().unwrap().to_string();let pointer=source.as_ptr()as usize;(handle,Some(source),pointer)});
  let(mut stock,mut born,mut released)=(source_grant,heap.requested_bytes,heap.released_bytes);let mut access=ArtifactInferenceSessionAccess::<String>::default();let mut done=false;let mut turns=0;
  while turns<stop&&!done{
   let demand=handle.inference_admission_demands(&access).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};
   for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant})].into_iter().flatten(){
    let before=position(&access);let source_before=source.as_ref().map(|value|value.as_ptr()as usize);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(denied,|cx|advance(&handle,&mut access,&mut source,cx)));assert!(result.unwrap().is_none());assert_eq!(position(&access),before);assert_eq!(source.as_ref().map(|value|value.as_ptr()as usize),source_before);assert_eq!(caller.receipt(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
   }
   let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|advance(&handle,&mut access,&mut source,cx)));let result=result.unwrap();if let Some(found)=result{assert_eq!(found,pointer);done=true}let receipt=caller.receipt();debit(&mut stock,receipt,heap,&mut born,&mut released);if let Some(original)=access.original(){assert_eq!(original.as_ptr()as usize,pointer)}turns+=1;assert!(turns<1000);
  }
  if stop==usize::MAX{assert!(done);assert!(access.original().is_none());let mut second=ArtifactInferenceSessionAccess::<String>::default();for _ in 0..1000{let demand=handle.inference_admission_demands(&second).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|advance(&handle,&mut second,&mut source,cx)));let result=result.unwrap();debit(&mut stock,caller.receipt(),heap,&mut born,&mut released);if let Some(found)=result{assert_eq!(found,pointer);break}}assert_eq!(second.phase,5);}
  if stop!=usize::MAX{let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(caller.cancel().cancel()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let before=position(&access);let demand=handle.inference_admission_demands(&access).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|advance(&handle,&mut access,&mut source,cx)));assert!(result.unwrap().is_none());assert_eq!(position(&access),before);assert_eq!(caller.receipt(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  let mut pending=ControlledRetirement::new((access,source)).unwrap();
  for _ in 0..10000{if pending.terminal_is_empty(){break}let demand=pending.selected_demand(body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|semio_framework_job::close_original_retained_step(cx,demand,|grant|pending.step(grant)).map(|_|())));result.unwrap();debit(&mut stock,caller.receipt(),heap,&mut born,&mut released)}assert!(pending.terminal_is_empty());assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(pending)).1.released_bytes,0);
  let mut alias=ArtifactInstanceOperationOwnerAliasRetirement::new(handle);
  for _ in 0..10000{if alias.terminal_is_empty(){break}let demand=alias.demands(body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|semio_framework_plugin_ownership::bounded_ownership::original_lifecycle_step(cx,grant,demand,|cx,grant|{let step=alias.step(cx,grant)?;let terminal=alias.terminal_is_empty();Ok((PluginLifecycleStep::retained(step,terminal),terminal))}).map(|_|()).map_err(OriginalTurnFailure::from)));result.unwrap();debit(&mut stock,caller.receipt(),heap,&mut born,&mut released)}
  assert!(alias.terminal_is_empty());assert_eq!(born,released);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(alias)).1.released_bytes,0);caller.retire(source_grant);
 }}
}
